export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const g = 9.8;
  const t = Math.max(0, time);
  const velocity = launchSpeed - g * t;
  const height = Math.max(0, launchSpeed * t - 0.5 * g * t * t);
  const apexTime = launchSpeed / g;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * g);

  let motionStateText = "Still for an instant";
  if (velocity > 0.05) {
    motionStateText = "Moving up";
  } else if (velocity < -0.05) {
    motionStateText = "Moving down";
  }
  const gravityStateText = "Gravity pulls down";

  const originX = 220;
  const originY = 360;
  const pixelsPerMeter = 160;

  const ballX = originX;
  const ballY = originY - height * pixelsPerMeter;

  const objects = [];

  objects.push(sdk.line("height_scale_line", 140, originY, 140, originY - 1.6 * pixelsPerMeter, { role: "neutral" }));
  for (let m = 0; m <= 1.5; m += 0.5) {
    const yPos = originY - m * pixelsPerMeter;
    objects.push(sdk.line(`scale_tick_${m}`, 135, yPos, 145, yPos, { role: "neutral" }));
    objects.push(sdk.text(`scale_text_${m}`, 125, yPos + 4, `${m.toFixed(1)} m`, { align: "end", role: "neutral" }));
  }

  objects.push(sdk.line("launch_guide", 150, originY, 290, originY, { role: "neutral", opacity: 0.5 }));
  objects.push(sdk.text("launch_guide_label", 295, originY + 4, "Launch height", { align: "start", role: "neutral" }));

  const apexY = originY - apexHeight * pixelsPerMeter;
  objects.push(sdk.line("apex_guide", 150, apexY, 290, apexY, { role: "warning", opacity: 0.6 }));
  objects.push(sdk.text("apex_guide_label", 295, apexY + 4, `Top (${apexHeight.toFixed(2)} m)`, { align: "start", role: "warning" }));

  objects.push(sdk.circle("ball.toss", ballX, ballY, 28, { role: "learner" }));

  const vScale = 15;
  const vVec = sdk.vector("vec.v", { x: ballX + 24, y: ballY }, { value: Math.abs(velocity), direction: velocity >= 0 ? "up" : "down", scale: vScale, minLength: 12, label: "v", role: "learner" });
  if (Math.abs(velocity) > 0.05) {
    objects.push(...vVec);
  }

  const aVec = sdk.vector("vec.a", { x: ballX - 24, y: ballY }, { value: g, direction: "down", scale: 4, minLength: 12, label: "a", role: "warning" });
  objects.push(...aVec);

  const calloutLines = [motionStateText, gravityStateText];
  const calloutObjs = sdk.callout(ballX + 45, ballY - 20, calloutLines, { id: "callout.toss", role: "tutor" });
  objects.push(...calloutObjs);

  return {
    frame: sdk.frame(objects, {
      width: 640,
      height: 420,
      readouts: [
        { id: "motionState", value: motionStateText },
        { id: "gravityState", value: gravityStateText }
      ]
    }),
    quantities: {
      launchSpeed,
      gravity: g,
      apexTime,
      apexHeight,
      velocity,
      height
    }
  };
}
